def tr(key, lang="en", **kwargs):
    value = TEXT[key][1 if lang == "ta" else 0]
    return value.format(**kwargs) if kwargs else value


def choices(keys, lang):
    return [(tr(k, lang), k) for k in keys]


def example_text(key, lang):
    return EXAMPLES[key][1 if lang == "ta" else 0]
